void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize coordinates
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv = uv * 2.0 - 1.0; // Convert to [-1, 1]
    uv.x *= iResolution.x / iResolution.y; // Maintain aspect ratio

    // Scope parameters
    float outerRadius = 0.8; // Radius of the outer circle (scope boundary)
    float innerRadius = 0.6; // Radius of the inner circle (reticle)
    float parallaxStrength = 0.8; // Strength of the parallax effect

    // Calculate distance from center
    float distFromCenter = length(uv);

    // Check if we are within the outer circle (scope boundary)
    if (distFromCenter > outerRadius) {
        fragColor = vec4(0.0); // Outside the scope, black background
        return;
    }

    // Simulate parallax using mouse movement
    vec2 mouseNorm = (iMouse.xy / iResolution.xy) * 2.0 - 1.0; // Normalize mouse position
    mouseNorm.x *= iResolution.x / iResolution.y; // Adjust for aspect ratio
    vec2 parallaxOffset = mouseNorm * parallaxStrength; // Invert direction for opposite movement

    // Apply parallax offset to the UV coordinates of the inner circle
    vec2 innerUV = uv + parallaxOffset;

    // Compute distance from the center of the inner circle
    float distFromInnerCenter = length(innerUV);

    // Initialize color
    vec4 color = vec4(0.2, 0.2, 0.2, 1.0); // Background within the scope

    // Draw the inner circle (reticle)
    if (distFromInnerCenter < innerRadius) {
        color = vec4(1.0, 0.5, 0.2, 1.0); // Inner circle color

        // Add a fixed UV plus reticle visible only in the inner circle
        float lineWidth = 0.02; // Thickness of the plus lines
        if (abs(uv.x) < lineWidth || abs(uv.y) < lineWidth) {
            color = vec4(0.0, 1.0, 0.0, 1.0); // Plus reticle color
        }
    }

    fragColor = color;
}
